import React, { useState, useCallback, useMemo } from "react";
import { Column, User } from "../types";
import { UserTable } from "../components/table/UserTable";


interface UsersPageProps {
  // Add any props from your API/context here
}

export const UsersPage: React.FC<UsersPageProps> = () => {
  // Sample data - replace with your actual data fetching
  const [users, setUsers] = useState<User[]>([
    // ... your users data
  ]);

  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [sortConfig, setSortConfig] = useState<{
    key: keyof User;
    direction: "asc" | "desc";
  } | null>(null);

  // Define columns for the table
  const columns: Column[] = [
    { key: "phone", label: "Phone" },
    { key: "email", label: "Email" },
    { key: "location", label: "Location" },
  ];

  // Handle sorting
  const handleSort = useCallback((key: keyof User) => {
    setSortConfig((prev) => {
      if (prev?.key === key) {
        return {
          key,
          direction: prev.direction === "asc" ? "desc" : "asc",
        };
      }
      return { key, direction: "asc" };
    });
  }, []);

  // Sort users
  const sortedUsers = useMemo(() => {
    if (!sortConfig) return users;

    const sorted = [...users].sort((a, b) => {
      const aVal = a[sortConfig.key];
      const bVal = b[sortConfig.key];

      if (aVal == null) return 1;
      if (bVal == null) return -1;

      if (typeof aVal === "string" && typeof bVal === "string") {
        return sortConfig.direction === "asc"
          ? aVal.localeCompare(bVal)
          : bVal.localeCompare(aVal);
      }

      return sortConfig.direction === "asc"
        ? aVal < bVal
          ? -1
          : 1
        : aVal > bVal
        ? -1
        : 1;
    });

    return sorted;
  }, [users, sortConfig]);

  // Handle suspend user
  const handleSuspendUser = useCallback(async (user: User) => {
    try {
      // TODO: Call your API to suspend the user
      console.log("Suspending user:", user);

      // Update local state
      setUsers((prev) =>
        prev.map((u) =>
          u.id === user.id ? { ...u, is_suspended: true } : u
        )
      );

      // Close detail panel after suspending
      setSelectedUser(null);
    } catch (error) {
      console.error("Failed to suspend user:", error);
    }
  }, []);

  // ─── CONDITIONAL RENDERING ───
  // If a user is selected, show the detail panel
  if (selectedUser) {
    return (
      <UserDetailPanel
        user={selectedUser}
        onClose={() => setSelectedUser(null)}
        onSuspend={handleSuspendUser}
      />
    );
  }

  // Otherwise, show the users table
  return (
    <UserTable
      data={sortedUsers}
      columns={columns}
      onSort={handleSort}
      sortConfig={sortConfig}
      rowsPerPage={10}
      onViewUser={(user) => setSelectedUser(user)}
      onSuspendUser={handleSuspendUser}
    />
  );
};

export default UsersPage;
